import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the Azure Virtual Desktop workload assessment (AVD in Azure)","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-avd-azure-workload-checklist.md","filePath":"frameworks/waf-avd-azure-workload-checklist.md"}'),d={name:"frameworks/waf-avd-azure-workload-checklist.md"};function s(i,t,n,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="waf-—-enumerated-source-for-the-azure-virtual-desktop-workload-assessment-avd-in-azure" tabindex="-1">WAF — enumerated source for the Azure Virtual Desktop workload assessment (AVD in Azure) <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-virtual-desktop-workload-assessment-avd-in-azure" aria-label="Permalink to &quot;WAF — enumerated source for the Azure Virtual Desktop workload assessment (AVD in Azure)&quot;">​</a></h1><p><strong>Enumerated 2026-11-24. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.avd.yaml</code> scores Azure Virtual Desktop deployed <strong>on Azure Local</strong> (see <a href="./waf-avd-workload-checklist.html">waf-avd-workload-checklist.md</a>). This page enumerates the companion review for AVD running <strong>in Azure</strong>, which is the scope of Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/1ef67c4e-b8d1-4193-b850-d192089ae33d/" target="_blank" rel="noreferrer">Azure Well-Architected Azure Virtual Desktop workload</a> assessment. <code>src/assess/rules/waf.avd.azure.yaml</code> is written against this page only, and every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/1ef67c4e-b8d1-4193-b850-d192089ae33d/" target="_blank" rel="noreferrer">Azure Well-Architected Azure Virtual Desktop workload</a> (60 minutes, multiple choice; question text not published)</td></tr><tr><td>Framework version</td><td>Azure Virtual Desktop guidance on Microsoft Learn, current; ARM <code>Microsoft.DesktopVirtualization</code> latest GA API 2025-10-10</td></tr><tr><td>Extraction date</td><td>2026-11-24</td></tr><tr><td>Verification method</td><td>Each source page below was fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-24. Every ARM property an automated item reads was checked against the <code>Microsoft.DesktopVirtualization</code> ARM template reference or the SDK reference.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published, and the WAF AVD design-area pages (<code>well-architected/azure-virtual-desktop/*</code>) now redirect to AVD product pages or return 404. The items below are <strong>Scout&#39;s</strong> reading of the live AVD guidance, and the <code>WAF-AVDAZ-*</code> IDs are Scout&#39;s.</p><p>Sources:</p><ul><li>[SEC] <a href="https://learn.microsoft.com/azure/virtual-desktop/security-recommendations" target="_blank" rel="noreferrer">Security recommendations for Azure Virtual Desktop</a></li><li>[BCDR] <a href="https://learn.microsoft.com/azure/architecture/example-scenario/azure-virtual-desktop/azure-virtual-desktop-multi-region-bcdr" target="_blank" rel="noreferrer">Multiregion business continuity for Azure Virtual Desktop</a></li><li>[SVOC] <a href="https://learn.microsoft.com/azure/virtual-desktop/start-virtual-machine-connect" target="_blank" rel="noreferrer">Start VM on Connect</a></li><li>[AUTO] <a href="https://learn.microsoft.com/azure/virtual-desktop/autoscale-scenarios" target="_blank" rel="noreferrer">Autoscale scaling plans</a></li><li>[VAL] <a href="https://learn.microsoft.com/azure/virtual-desktop/configure-validation-environment" target="_blank" rel="noreferrer">Configure a validation environment</a></li><li>[SAU] <a href="https://learn.microsoft.com/azure/virtual-desktop/scheduled-agent-updates" target="_blank" rel="noreferrer">Scheduled Agent Updates</a></li><li>[PL] <a href="https://learn.microsoft.com/azure/virtual-desktop/private-link-setup" target="_blank" rel="noreferrer">Private Link with Azure Virtual Desktop</a></li><li>[INS] <a href="https://learn.microsoft.com/azure/virtual-desktop/insights" target="_blank" rel="noreferrer">Azure Virtual Desktop Insights</a></li><li>[FSL] <a href="https://learn.microsoft.com/azure/virtual-desktop/store-fslogix-profile" target="_blank" rel="noreferrer">Storage options for FSLogix profile containers</a></li><li>[DEP] <a href="https://learn.microsoft.com/azure/virtual-desktop/deploy-azure-virtual-desktop" target="_blank" rel="noreferrer">Deploy Azure Virtual Desktop</a></li></ul><p>Automated items are <strong>gated</strong>: they run only when the relevant AVD resources exist, so an estate with no AVD reports them Not assessed. Joins to virtual machines use the session host&#39;s <code>resourceId</code>; session hosts on Azure Local are not Azure VMs, so they drop out of those items rather than being mis-scored.</p><h2 id="the-enumeration-—-30-items-across-the-five-pillars" tabindex="-1">The enumeration — 30 items across the five pillars <a class="header-anchor" href="#the-enumeration-—-30-items-across-the-five-pillars" aria-label="Permalink to &quot;The enumeration — 30 items across the five pillars&quot;">​</a></h2><h3 id="reliability-waf-avdaz-re-—-6-items" tabindex="-1">Reliability (WAF-AVDAZ-RE) — 6 items <a class="header-anchor" href="#reliability-waf-avdaz-re-—-6-items" aria-label="Permalink to &quot;Reliability (WAF-AVDAZ-RE) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AVDAZ-RE-01</td><td>Session-host VMs are deployed in availability zones</td><td>✅ session host → VM with no zone in a zone-capable region</td><td>BCDR, DEP</td></tr><tr><td>WAF-AVDAZ-RE-02</td><td>Session hosts are healthy (Shutdown is not a failure)</td><td>✅ session-host status</td><td>INS</td></tr><tr><td>WAF-AVDAZ-RE-03</td><td>FSLogix profile storage is zone- or geo-redundant</td><td>❌ Manual — storage accounts attached</td><td>BCDR, FSL</td></tr><tr><td>WAF-AVDAZ-RE-04</td><td>Profile shares are backed up</td><td>❌ Manual — protected items attached</td><td>BCDR</td></tr><tr><td>WAF-AVDAZ-RE-05</td><td>The golden image is in a Compute Gallery and replicated to the recovery region</td><td>❌ Manual</td><td>BCDR</td></tr><tr><td>WAF-AVDAZ-RE-06</td><td>A business continuity model is defined and recovery is tested</td><td>❌ Manual</td><td>BCDR</td></tr></tbody></table><h3 id="security-waf-avdaz-se-—-11-items" tabindex="-1">Security (WAF-AVDAZ-SE) — 11 items <a class="header-anchor" href="#security-waf-avdaz-se-—-11-items" aria-label="Permalink to &quot;Security (WAF-AVDAZ-SE) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AVDAZ-SE-01</td><td>Host pool public network access is restricted</td><td>✅ <code>publicNetworkAccess</code></td><td>PL</td></tr><tr><td>WAF-AVDAZ-SE-02</td><td>Workspace public network access is disabled</td><td>✅ <code>publicNetworkAccess</code></td><td>PL</td></tr><tr><td>WAF-AVDAZ-SE-03</td><td>Host pools have a private endpoint</td><td>✅ host pool → private endpoint</td><td>PL</td></tr><tr><td>WAF-AVDAZ-SE-04</td><td>Workspaces have a private endpoint</td><td>✅ workspace → private endpoint</td><td>PL</td></tr><tr><td>WAF-AVDAZ-SE-05</td><td>Microsoft Defender for Servers is enabled</td><td>✅ Defender plan tier (per subscription)</td><td>SEC</td></tr><tr><td>WAF-AVDAZ-SE-06</td><td>MFA and Conditional Access are required for AVD</td><td>❌ Manual — needs Microsoft Graph</td><td>SEC</td></tr><tr><td>WAF-AVDAZ-SE-07</td><td>Session hosts use Trusted Launch or Confidential VMs, with encryption at host</td><td>❌ Manual</td><td>SEC, DEP</td></tr><tr><td>WAF-AVDAZ-SE-08</td><td>No direct RDP or public inbound to session hosts</td><td>❌ Manual — internet-open NSG rules attached</td><td>SEC</td></tr><tr><td>WAF-AVDAZ-SE-09</td><td>Session hosts are assessed for updates automatically</td><td>✅ session host → VM <code>assessmentMode</code></td><td>SEC</td></tr><tr><td>WAF-AVDAZ-SE-10</td><td>Session hosts are hardened in the guest</td><td>❌ Manual — Intune / Group Policy</td><td>SEC</td></tr><tr><td>WAF-AVDAZ-SE-11</td><td>Device redirection is restricted</td><td>❌ Manual</td><td>SEC</td></tr></tbody></table><h3 id="cost-optimization-waf-avdaz-co-—-5-items" tabindex="-1">Cost optimization (WAF-AVDAZ-CO) — 5 items <a class="header-anchor" href="#cost-optimization-waf-avdaz-co-—-5-items" aria-label="Permalink to &quot;Cost optimization (WAF-AVDAZ-CO) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AVDAZ-CO-01</td><td>Every pooled host pool has an enabled scaling plan</td><td>✅ pooled host pool → enabled scaling-plan assignment</td><td>AUTO</td></tr><tr><td>WAF-AVDAZ-CO-02</td><td>Personal host pools use Start VM on Connect</td><td>✅ <code>startVMOnConnect</code></td><td>SVOC</td></tr><tr><td>WAF-AVDAZ-CO-03</td><td>Windows licence benefit is applied to session hosts</td><td>✅ session host → Windows VM with no <code>licenseType</code></td><td>DEP</td></tr><tr><td>WAF-AVDAZ-CO-04</td><td>Pooled host pools set a deliberate maximum session limit</td><td>✅ <code>maxSessionLimit</code> at the default</td><td>AUTO</td></tr><tr><td>WAF-AVDAZ-CO-05</td><td>Session-host sizes and profile storage tier match measured demand</td><td>❌ Manual — VMs attached</td><td>FSL</td></tr></tbody></table><h3 id="operational-excellence-waf-avdaz-oe-—-5-items" tabindex="-1">Operational excellence (WAF-AVDAZ-OE) — 5 items <a class="header-anchor" href="#operational-excellence-waf-avdaz-oe-—-5-items" aria-label="Permalink to &quot;Operational excellence (WAF-AVDAZ-OE) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AVDAZ-OE-01</td><td>A validation host pool exists for service updates</td><td>✅ <code>validationEnvironment</code></td><td>VAL</td></tr><tr><td>WAF-AVDAZ-OE-02</td><td>Agent updates are scheduled</td><td>✅ <code>agentUpdate.type</code></td><td>SAU</td></tr><tr><td>WAF-AVDAZ-OE-03</td><td>Host pools, workspaces and session hosts send diagnostics to Log Analytics</td><td>❌ Manual — data collection rules attached</td><td>INS</td></tr><tr><td>WAF-AVDAZ-OE-04</td><td>No session-host component update has failed</td><td>✅ <code>updateState</code></td><td>SAU, INS</td></tr><tr><td>WAF-AVDAZ-OE-05</td><td>Service Health and metric alerts cover AVD</td><td>❌ Manual — activity-log alert rules attached</td><td>SEC</td></tr></tbody></table><h3 id="performance-efficiency-waf-avdaz-pe-—-3-items" tabindex="-1">Performance efficiency (WAF-AVDAZ-PE) — 3 items <a class="header-anchor" href="#performance-efficiency-waf-avdaz-pe-—-3-items" aria-label="Permalink to &quot;Performance efficiency (WAF-AVDAZ-PE) — 3 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AVDAZ-PE-01</td><td>Session-host OS disks are Premium SSD</td><td>❌ Manual</td><td>DEP</td></tr><tr><td>WAF-AVDAZ-PE-02</td><td>Profile storage is in the host pool&#39;s region and sized for the user count</td><td>❌ Manual — host pools attached</td><td>FSL</td></tr><tr><td>WAF-AVDAZ-PE-03</td><td>RDP Shortpath (UDP) is used</td><td>❌ Manual</td><td>PL</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>6</td><td>2</td><td>4</td></tr><tr><td>Security</td><td>11</td><td>6</td><td>5</td></tr><tr><td>Cost optimization</td><td>5</td><td>4</td><td>1</td></tr><tr><td>Operational excellence</td><td>5</td><td>3</td><td>2</td></tr><tr><td>Performance efficiency</td><td>3</td><td>0</td><td>3</td></tr><tr><td><strong>Total</strong></td><td><strong>30</strong></td><td><strong>15</strong></td><td><strong>15</strong></td></tr></tbody></table><p>Fields added to the assessment collection for these items (2026-11-24): host pool <code>id</code>, <code>location</code>, <code>startVMOnConnect</code>, <code>validationEnvironment</code>, <code>publicNetworkAccess</code>, <code>agentUpdateType</code>, <code>preferredAppGroupType</code>; session host <code>resourceId</code>, <code>updateState</code>; scaling plan <code>enabledHostPools</code>; and a new <code>compute.avdWorkspaces</code> dataset. The host pool registration token is never collected.</p>',24)])])}const p=e(d,[["render",s]]);export{A as __pageData,p as default};
